function deletePrinter(id){const p=pById(id);if(!p)return;A.confirmDialog('حذف الطابعة',`سيتم حذف إعداد ${p.name} من هذا الجهاز فقط.`,()=>{store.printers=store.printers.filter(x=>x.id!==id);for(const k of Object.keys(store.defaults))if(store.defaults[k]===id)store.defaults[k]='';runtime.usb.delete(id);runtime.serial.delete(id);runtime.ble.delete(id);persist();rerenderPrinterPanel();A.closeModal?.();A.toast('تم حذف الطابعة المحفوظة.','success')})}
