async function discoverModal(){refreshStore();const authorized=[];if(navigator.usb)try{for(const d of await navigator.usb.getDevices())authorized.push({type:'USB مصرح',name:d.productName||'USB Printer',detail:`VID ${d.vendorId} / PID ${d.productId}`})}catch(_){}if(navigator.serial)try{for(const p of await navigator.serial.getPorts()){const i=p.getInfo?.()||{};authorized.push({type:'Serial مصرح',name:'Serial / ESC-POS',detail:`VID ${i.usbVendorId||'—'} / PID ${i.usbProductId||'—'}`})}}catch(_){}if(navigator.bluetooth?.getDevices)try{for(const d of await navigator.bluetooth.getDevices())authorized.push({type:'Bluetooth مصرح',name:d.name||'Bluetooth Device',detail:d.id||''})}catch(_){}let qzList=[],qzErr=MOBILE_DEVICE?'QZ Tray غير مستخدم على الجوال. استخدم Bluetooth المباشر.':'اضغط زر طابعات Windows عبر QZ للبحث عند الحاجة.';A.openModal({title:'البحث عن الطابعات',size:'modal-lg',hideSubmit:true,body:`<div class="pm-form-note"><b>مهم:</b> ${ANDROID_DEVICE?'على Android تم إلغاء مسار Serial الخاطئ. اختر <b>Bluetooth مباشر (BLE)</b>؛ طابعات Xprinter XP-P323B ثنائية الوضع تعمل بهذا المسار، وبعد أول إذن يعاد الاتصال تلقائياً.':'استخدم Bluetooth BLE للطابعات اللاسلكية أو Serial فقط على الكمبيوتر. QZ Tray للكمبيوتر.'}</div><div class="pm-discovery-actions"><button type="button" class="btn btn-primary" data-action="pm-add-usb">${A.I?.('usb',16)||''} إضافة USB</button>${ANDROID_DEVICE?`<button type="button" class="btn btn-primary" data-action="pm-add-bluetooth">${A.I?.('bluetooth',16)||''} Bluetooth مباشر (Android)</button>`:`<button type="button" class="btn btn-secondary" data-action="pm-add-serial">Serial / ESC-POS</button><button type="button" class="btn btn-secondary" data-action="pm-add-bluetooth">${A.I?.('bluetooth',16)||''} Bluetooth BLE</button>`}<button type="button" class="btn btn-secondary" data-action="pm-add-qz">${A.I?.('print',16)||''} طابعات Windows عبر QZ</button></div><h4>الأجهزة التي سبق منحها إذنًا</h4>${authorized.length?`<div class="pm-discovered">${authorized.map(x=>`<div class="pm-discovered-row static"><span>${A.I?.('print',18)||''}</span><div><b>${esc(x.name)}</b><small>${esc(x.type)} — ${esc(x.detail)}</small></div></div>`).join('')}</div>`:'<p class="pm-muted">لا توجد أجهزة مباشرة سبق منحها إذنًا.</p>'}<h4>طابعات Windows عبر QZ Tray</h4>${qzList.length?`<div class="pm-discovered">${qzList.map(n=>`<button type="button" class="pm-discovered-row" data-action="pm-add-qz-name" data-name="${esc(n)}"><span>${A.I?.('print',18)||''}</span><div><b>${esc(n)}</b><small>Windows / QZ Tray</small></div><em>إضافة</em></button>`).join('')}</div>`:`<p class="pm-muted">${esc(qzErr||'QZ Tray غير متصل أو لا توجد طابعات.')}</p>`}`})}
function optionPrinters(selected,filter){const arr=filter?store.printers.filter(filter):store.printers;return`<option value="">غير محدد</option>${arr.map(p=>`<option value="${esc(p.id)}" ${p.id===selected?'selected':''}>${esc(p.name)} — ${paperLabel(p.paperSize,p)}</option>`).join('')}`}
function printerPanelHtml(){refreshStore();const cards=store.printers.map(p=>`<article class="pm-card" data-printer-id="${esc(p.id)}"><div class="pm-card-top"><span class="pm-printer-icon">${A.I?.('print',20)||''}</span><div class="pm-card-name"><b>${esc(p.name)}</b><small>${esc([p.brand,p.model].filter(Boolean).join(' ')||connectionLabel(p.connection))}</small></div><span class="pm-status ${statusClass(p.status)}">${stateLabel(p.status)}</span></div><div class="pm-meta"><span>${connectionLabel(p.connection)}</span><span>${paperLabel(p.paperSize,p)}</span><span>${capabilityText(p)}</span>${p.usbVendorId?`<span>VID ${esc(p.usbVendorId)} · PID ${esc(p.usbProductId||'—')}</span>`:''}${p.ip?`<span>${esc(p.ip)}:${Number(p.port||9100)}</span>`:''}</div>${p.lastError?`<div class="pm-card-error">${esc(p.lastError)}</div>`:''}<div class="pm-card-actions"><button type="button" class="btn btn-primary btn-sm" data-action="pm-test" data-id="${esc(p.id)}">اختبار</button><button type="button" class="btn btn-secondary btn-sm" data-action="pm-edit" data-id="${esc(p.id)}">تعديل</button><button type="button" class="btn btn-secondary btn-sm" data-action="pm-default" data-id="${esc(p.id)}">تعيين افتراضي</button><button type="button" class="btn btn-secondary btn-sm" data-action="pm-reconnect" data-id="${esc(p.id)}">إعادة اتصال</button><button type="button" class="btn btn-ghost btn-sm" data-action="pm-delete" data-id="${esc(p.id)}">حذف</button></div></article>`).join('');return`<section class="setting-group pm-settings-section settings-v771-wide" id="printerManagerSection" data-setting-key="مدير الطابعات"><div class="pm-head"><div><h3>مدير الطابعات الاحترافي</h3><p>طابعات متعددة، ESC/POS، USB، Bluetooth، Windows/QZ وNetwork Bridge مع رجوع تلقائي لطباعة النظام.</p></div><span class="pm-local-badge">إعدادات محلية · Offline</span></div><div class="pm-global-grid"><label class="field"><span>طريقة الطباعة</span><select id="pmGlobalMethod"><option value="auto" ${store.method==='auto'?'selected':''}>تلقائي</option><option value="browser" ${store.method==='browser'?'selected':''}>طباعة المتصفح</option><option value="usb" ${store.method==='usb'?'selected':''}>USB مباشر</option><option value="escpos" ${store.method==='escpos'?'selected':''}>ESC/POS</option><option value="qz" ${store.method==='qz'?'selected':''}>QZ Tray / Print Bridge</option></select></label><label class="check-row"><input id="pmFallback" type="checkbox" ${store.fallbackBrowser!==false?'checked':''}><span>استخدام طباعة النظام تلقائيًا عند فشل الاتصال المباشر</span></label><label class="check-row"><input id="pmAutoAfterSave" type="checkbox" ${store.autoPrintAfterSave!==false?'checked':''}><span>طباعة تلقائية بعد حفظ الفاتورة</span></label></div><div class="pm-defaults"><label class="field"><span>الفواتير الحرارية</span><select data-pm-default="invoice">${optionPrinters(store.defaults.invoice,p=>p.kind!=='standard'&&p.paperSize!=='a4')}</select></label><label class="field"><span>طابعة A4</span><select data-pm-default="a4">${optionPrinters(store.defaults.a4,p=>p.paperSize==='a4'||p.kind==='standard')}</select></label><label class="field"><span>التقارير</span><select data-pm-default="reports">${optionPrinters(store.defaults.reports)}</select></label><label class="field"><span>الإيصالات</span><select data-pm-default="receipts">${optionPrinters(store.defaults.receipts)}</select></label><label class="field"><span>المطبخ (لاحقًا)</span><select data-pm-default="kitchen">${optionPrinters(store.defaults.kitchen)}</select></label></div><div class="pm-toolbar"><button type="button" class="btn btn-primary" data-action="pm-discover">${A.I?.('search',16)||''} البحث عن الطابعات</button><button type="button" class="btn btn-secondary" data-action="pm-add-manual">${A.I?.('add',16)||'+'} إضافة طابعة</button><button type="button" class="btn btn-secondary pm-bixolon" data-action="pm-bixolon">BIXOLON SRP-B300 Preset</button><button type="button" class="btn btn-secondary" data-action="pm-add-qz">طابعات Windows / QZ</button></div><div class="pm-browser-note"><b>طابعة النظام / Windows:</b> بدون QZ Tray لا يدّعي التطبيق أنه يستطيع قراءة قائمة طابعات Windows أو الطباعة الصامتة بالاسم؛ عندها تُستخدم نافذة الطباعة الأصلية للنظام ليختار المستخدم أي طابعة مثبتة.</div><div class="pm-cards">${cards||'<div class="pm-empty">لا توجد طابعات محفوظة بعد. أضف BIXOLON SRP-B300 أو ابحث عن طابعة.</div>'}</div></section>`}
function bindPanel(section){section.querySelector('#pmGlobalMethod')?.addEventListener('change',e=>{store.method=e.target.value;persist()});section.querySelector('#pmFallback')?.addEventListener('change',e=>{store.fallbackBrowser=e.target.checked;persist()});section.querySelector('#pmAutoAfterSave')?.addEventListener('change',e=>{store.autoPrintAfterSave=e.target.checked;persist();syncCashierPrintCheckbox()});section.querySelectorAll('[data-pm-default]').forEach(s=>s.addEventListener('change',e=>{store.defaults[e.currentTarget.dataset.pmDefault]=e.currentTarget.value;persist()}));A.injectIcons?.(section);A.enhanceSelects?.(section)}
function mountSettings(root){if(!root||root.querySelector('#printerManagerSection'))return;const form=root.querySelector('#settingsForm'),grid=form?.querySelector('.grid-equal');if(!grid)return;const holder=document.createElement('div');holder.innerHTML=printerPanelHtml();const section=holder.firstElementChild;grid.appendChild(section);bindPanel(section);const nav=root.querySelector('.settings-v771-nav');if(nav&&!nav.querySelector('[data-setting-jump="مدير الطابعات"]')){const b=document.createElement('button');b.type='button';b.dataset.settingJump='مدير الطابعات';b.textContent='الطابعات';b.onclick=()=>section.scrollIntoView({behavior:'smooth',block:'start'});nav.appendChild(b)}}
function rerenderPrinterPanel(){const old=document.querySelector('#printerManagerSection');if(!old)return;const h=document.createElement('div');h.innerHTML=printerPanelHtml();const n=h.firstElementChild;old.replaceWith(n);bindPanel(n)}
function syncCashierPrintCheckbox(){const el=document.querySelector('input[name="print"]');if(el&&!el.dataset.pmInitialized){el.checked=store.autoPrintAfterSave!==false;el.dataset.pmInitialized='1'}}
function installObserver(){if(runtime.observer)return;let queued=false;const target=document.querySelector('#workspace')||document.body;runtime.observer=new MutationObserver(()=>{if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;try{if(A.state?.view==='settings')mountSettings(document.querySelector('#workspace'));syncCashierPrintCheckbox()}catch(e){console.error('Printer observer failed',e)}})});runtime.observer.observe(target,{childList:true,subtree:false})}
async function autoReconnect(){refreshStore();for(const p of store.printers.filter(x=>x.autoConnect)){try{if(['usb','serial','bluetooth'].includes(p.connection))await reconnect(p.id,false);else if((p.connection==='qz'||p.connection==='network')&&store.method!=='browser')await reconnect(p.id,false);else if(p.connection==='system')updatePrinter(p.id,{status:'ready'})}catch(e){const msg=safeError(e);updatePrinter(p.id,{status:/إذن/.test(msg)?'permission':'disconnected',lastError:''})}}rerenderPrinterPanel()}
async function exportInvoiceImage(id){const s=invoice(id);if(!s)return A.toast('الفاتورة غير موجودة.','error');try{const p=browserProfile(defaultPrinter('invoice')),c=await receiptCanvas(s,p,2),blob=await new Promise((res,rej)=>c.toBlob(b=>b?res(b):rej(Error('تعذر إنشاء الصورة.')),'image/png'));A.downloadBlob(`فاتورة-${s.number}.png`,blob,'image/png');A.toast('تم تجهيز صورة الفاتورة بجودة عالية','success')}catch(e){A.toast(safeError(e),'error')}}
function pdfFromCanvas(canvas,p){const dataUrl=canvas.toDataURL('image/jpeg',.97),b64=dataUrl.split(',')[1]||'',bin=atob(b64),jpg=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)jpg[i]=bin.charCodeAt(i);const enc=s=>new TextEncoder().encode(s),cat=concatBytes;let w,h;if(p?.paperSize==='a4'){const maxW=595.28,maxH=841.89,scale=Math.min(maxW/canvas.width,maxH/canvas.height);w=canvas.width*scale;h=canvas.height*scale}else{w=mmPrintable(p)*72/25.4;h=w*(canvas.height/canvas.width)}const objs=[];objs[1]=enc('1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n');objs[2]=enc('2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n');objs[3]=enc(`3 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${w.toFixed(2)} ${h.toFixed(2)}] /Resources << /XObject << /Im0 4 0 R >> >> /Contents 5 0 R >>\nendobj\n`);objs[4]=cat([enc(`4 0 obj\n<< /Type /XObject /Subtype /Image /Width ${canvas.width} /Height ${canvas.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpg.length} >>\nstream\n`),jpg,enc('\nendstream\nendobj\n')]);const stream=`q\n${w.toFixed(2)} 0 0 ${h.toFixed(2)} 0 0 cm\n/Im0 Do\nQ\n`;objs[5]=enc(`5 0 obj\n<< /Length ${enc(stream).length} >>\nstream\n${stream}endstream\nendobj\n`);const header=cat([enc('%PDF-1.4\n%'),new Uint8Array([0xe2,0xe3,0xcf,0xd3]),enc('\n')]);let offset=header.length,body=[header],offs=[0];for(let i=1;i<=5;i++){offs[i]=offset;body.push(objs[i]);offset+=objs[i].length}const xo=offset;let xref='xref\n0 6\n0000000000 65535 f \n';for(let i=1;i<=5;i++)xref+=String(offs[i]).padStart(10,'0')+' 00000 n \n';return new Blob([...body,enc(`${xref}trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${xo}\n%%EOF`)],{type:'application/pdf'})}
async function exportInvoicePdf(id){const s=invoice(id);if(!s)return A.toast('الفاتورة غير موجودة.','error');try{const p=browserProfile(defaultPrinter('invoice')),c=await receiptCanvas(s,p,2),blob=pdfFromCanvas(c,p);A.downloadBlob(`فاتورة-${s.number}.pdf`,blob,'application/pdf');A.toast('تم تجهيز PDF عالي الجودة','success')}catch(e){A.toast(safeError(e),'error')}}
// Actions
// v7.84.7: فاتورة البيع والطباعة/الصورة تستخدم مسار v7.81.6 الأصلي حرفياً.
