A.registerAction('pm-add-usb',()=>addUsb().then(()=>A.closeModal?.()).catch(e=>A.toast(safeError(e),'error',7000)));
A.registerAction('pm-add-serial',()=>addSerial().then(()=>A.closeModal?.()).catch(e=>A.toast(safeError(e),'error',7000)));
A.registerAction('pm-add-bluetooth',()=>addBluetooth().then(()=>A.closeModal?.()).catch(e=>A.toast(safeError(e),'error',7000)));
A.registerAction('pm-add-qz',()=>addQz().catch(e=>A.toast(safeError(e),'error',7000)));
A.registerAction('pm-add-qz-name',b=>{const name=b.dataset.name,p=makePrinter({name,connection:'qz',qzName:name,paperSize:/A4/i.test(name)?'a4':'80',status:'ready'});store.printers.push(p);if(!store.defaults.invoice)store.defaults.invoice=p.id;persist();A.closeModal?.();rerenderPrinterPanel();A.toast('تمت إضافة طابعة Windows عبر QZ Tray.','success')});
A.registerAction('pm-test',b=>printTest(b.dataset.id).catch(e=>A.toast(safeError(e),'error',7000)));A.registerAction('pm-edit',b=>editPrinter(b.dataset.id));A.registerAction('pm-default',b=>setDefault(b.dataset.id,'invoice'));A.registerAction('pm-reconnect',b=>reconnect(b.dataset.id,true).catch(e=>A.toast(safeError(e),'error',7000)));A.registerAction('pm-delete',b=>deletePrinter(b.dataset.id));
// v7.84.7: لا نستبدل واجهة Bluetooth القديمة حتى تبقى طباعة الفاتورة بنفس v7.81.6.
